  {"clause_id": "c050", "issues": [
    {"issue": "DISTRIBUTOR is barred from using any advertising or descriptive literature pertaining to PRODUCTS without prior written consent, while Section 3(ii)(v) makes DISTRIBUTOR \"solely responsible for any and all promotions, sales and marketing programs, advertising and the like.\" Which provision governs distributor-generated promotion would have to be construed.", "type": 2, "prob": 0.22}
